fn native_parse_at<'a>(bytes:&'a[u8],row:u8,offset:usize,log:&mut ParseLog)->Result<(&'a[u8],usize),Error> {
    let length = 5 + row_shape(row).unwrap().1;
    let framed = bytes
        .get(offset..offset + length)
